INSERT INTO classified_opinions (cluster_id, case_name, court, jurisdiction, opinion_type, charge_types, motion_types, defense_theories, motion_outcomes, motion_favorability, case_favorability, holding_text, is_good_law, classification_confidence, cross_validation_signals, classified_by, source_urls) VALUES ('2486030', 'State v. Dorsey', 'Supreme Court of Louisiana', 'la', 'order', ARRAY[]::text[], ARRAY[]::text[], ARRAY[]::text[], '[]'::jsonb, '[]'::jsonb, NULL, '| jOn May 17, 2006, Felton Dejuan Dorsey and Randy Wilson were indicted by a Caddo Parish grand jury for the first degree murder of Joe Prock and attempted first degree murder of Bobbie Prock. The state subsequently dismissed the latter charge against both by amendment. On May 18, 2006, the state gave notice of its intention to seek the death penalty at Dorsey’s (hereinafter “defendant”) trial, alleging five aggravating factors. On May 4, 2009, the state filed an amended notice of intent to seek', true, 'low_confidence', '{"charge_types":{"independent":0,"same_source":0,"details":[]},"motion_types":{"independent":0,"same_source":0,"details":[]},"defense_theories":{"independent":0,"same_source":0,"details":[]},"motion_outcomes":{"independent":0,"same_source":0,"details":[]}}'::jsonb, 'mechanical_pipeline_phase1', ARRAY['https://www.courtlistener.com/opinion/2486030/state-v-dorsey/']::text[]) ON CONFLICT (cluster_id) DO UPDATE SET case_name = EXCLUDED.case_name, court = EXCLUDED.court, jurisdiction = EXCLUDED.jurisdiction, charge_types = EXCLUDED.charge_types, motion_types = EXCLUDED.motion_types, defense_theories = EXCLUDED.defense_theories, motion_outcomes = EXCLUDED.motion_outcomes, motion_favorability = EXCLUDED.motion_favorability, case_favorability = EXCLUDED.case_favorability, holding_text = EXCLUDED.holding_text, classification_confidence = EXCLUDED.classification_confidence, cross_validation_signals = EXCLUDED.cross_validation_signals, classified_at = now(), updated_at = now();
INSERT INTO classified_opinions (cluster_id, case_name, court, jurisdiction, opinion_type, charge_types, motion_types, defense_theories, motion_outcomes, motion_favorability, case_favorability, holding_text, is_good_law, classification_confidence, cross_validation_signals, classified_by, source_urls) VALUES ('1287130', 'Knix v. State', 'Court of Appeals of Alaska', 'ak', 'order', ARRAY[]::text[], ARRAY[]::text[], ARRAY[]::text[], '[]'::jsonb, '[]'::jsonb, NULL, 'Codefendants Clint D. and Connie J. Knix appeal their convictions of perjury, AS 11.56.200(a), engaging in a scheme to defraud, AS 11.46.600(a)(2), and second-degree theft, AS 11.46.180(a) and AS 11.16.110(2)(B), raising various constitutional claims and statutory construction questions. We affirm the perjury and scheme to defraud convictions but hold that the theft convictions merge with the convictions for scheme to defraud.', true, 'low_confidence', '{"charge_types":{"independent":0,"same_source":0,"details":[]},"motion_types":{"independent":0,"same_source":0,"details":[]},"defense_theories":{"independent":0,"same_source":0,"details":[]},"motion_outcomes":{"independent":0,"same_source":0,"details":[]}}'::jsonb, 'mechanical_pipeline_phase1', ARRAY['https://www.courtlistener.com/opinion/1287130/knix-v-state/']::text[]) ON CONFLICT (cluster_id) DO UPDATE SET case_name = EXCLUDED.case_name, court = EXCLUDED.court, jurisdiction = EXCLUDED.jurisdiction, charge_types = EXCLUDED.charge_types, motion_types = EXCLUDED.motion_types, defense_theories = EXCLUDED.defense_theories, motion_outcomes = EXCLUDED.motion_outcomes, motion_favorability = EXCLUDED.motion_favorability, case_favorability = EXCLUDED.case_favorability, holding_text = EXCLUDED.holding_text, classification_confidence = EXCLUDED.classification_confidence, cross_validation_signals = EXCLUDED.cross_validation_signals, classified_at = now(), updated_at = now();
INSERT INTO classified_opinions (cluster_id, case_name, court, jurisdiction, opinion_type, charge_types, motion_types, defense_theories, motion_outcomes, motion_favorability, case_favorability, holding_text, is_good_law, classification_confidence, cross_validation_signals, classified_by, source_urls) VALUES ('1447803', 'State v. Williams', 'Arizona Supreme Court', 'az', 'order', ARRAY[]::text[], ARRAY[]::text[], ARRAY[]::text[], '[]'::jsonb, '[]'::jsonb, NULL, 'Arizona enhances sentences and imposes unique penalties for certain crimes, such as sexual assault and molestation, when committed against a minor under fifteen years old. A.R.S. § 13-604.01. These are called “dangerous crimes against children.” We are asked to decide whether the use of a motor vehicle which injures a person who fortuitously happens to be under fifteen years old is one of these crimes. We hold that it is not.', true, 'low_confidence', '{"charge_types":{"independent":0,"same_source":0,"details":[]},"motion_types":{"independent":0,"same_source":0,"details":[]},"defense_theories":{"independent":0,"same_source":0,"details":[]},"motion_outcomes":{"independent":0,"same_source":0,"details":[]}}'::jsonb, 'mechanical_pipeline_phase1', ARRAY['https://www.courtlistener.com/opinion/1447803/state-v-williams/']::text[]) ON CONFLICT (cluster_id) DO UPDATE SET case_name = EXCLUDED.case_name, court = EXCLUDED.court, jurisdiction = EXCLUDED.jurisdiction, charge_types = EXCLUDED.charge_types, motion_types = EXCLUDED.motion_types, defense_theories = EXCLUDED.defense_theories, motion_outcomes = EXCLUDED.motion_outcomes, motion_favorability = EXCLUDED.motion_favorability, case_favorability = EXCLUDED.case_favorability, holding_text = EXCLUDED.holding_text, classification_confidence = EXCLUDED.classification_confidence, cross_validation_signals = EXCLUDED.cross_validation_signals, classified_at = now(), updated_at = now();
