INSERT INTO classified_opinions (cluster_id, case_name, court, jurisdiction, opinion_type, charge_types, motion_types, defense_theories, motion_outcomes, motion_favorability, case_favorability, holding_text, is_good_law, classification_confidence, cross_validation_signals, classified_by, source_urls) VALUES ('782464', 'United States v. John Robert Andis', 'Court of Appeals for the Eighth Circuit', 'federal', 'order', ARRAY[]::text[], ARRAY[]::text[], ARRAY[]::text[], '[]'::jsonb, '[]'::jsonb, NULL, 'We granted en banc review of this appeal to determine under what circumstances a defendant can effectively waive appellate rights as part of a valid plea agreement. In this case, John R. Andis entered into a plea agreement that significantly limited his appellate rights.2 In spite of the waiver in his plea agreement, Mr. Andis now appeals certain conditions of his supervised release, claiming the conditions constitute an illegal sentence and therefore the waiver does not bar him from bringing th', true, 'low_confidence', '{"charge_types":{"independent":0,"same_source":0,"details":[]},"motion_types":{"independent":0,"same_source":0,"details":[]},"defense_theories":{"independent":0,"same_source":0,"details":[]},"motion_outcomes":{"independent":0,"same_source":0,"details":[]}}'::jsonb, 'mechanical_pipeline_phase1', ARRAY['https://www.courtlistener.com/opinion/782464/united-states-v-john-robert-andis/']::text[]) ON CONFLICT (cluster_id) DO UPDATE SET case_name = EXCLUDED.case_name, court = EXCLUDED.court, jurisdiction = EXCLUDED.jurisdiction, charge_types = EXCLUDED.charge_types, motion_types = EXCLUDED.motion_types, defense_theories = EXCLUDED.defense_theories, motion_outcomes = EXCLUDED.motion_outcomes, motion_favorability = EXCLUDED.motion_favorability, case_favorability = EXCLUDED.case_favorability, holding_text = EXCLUDED.holding_text, classification_confidence = EXCLUDED.classification_confidence, cross_validation_signals = EXCLUDED.cross_validation_signals, classified