INSERT INTO classified_opinions (cluster_id, case_name, court, jurisdiction, opinion_type, charge_types, motion_types, defense_theories, motion_outcomes, motion_favorability, case_favorability, holding_text, is_good_law, classification_confidence, cross_validation_signals, classified_by, source_urls) VALUES ('2588350', 'People v. Kelly', 'California Supreme Court', 'ca', 'order', ARRAY[]::text[], ARRAY[]::text[], ARRAY[]::text[], '[]'::jsonb, '[]'::jsonb, NULL, 'Article VI, section 14, of the California Constitution provides that “[decisions of the Supreme Court and courts of appeal that determine causes shall be in writing with reasons stated.” In this case, we consider what this constitutional mandate requires in a criminal appeal in which defense counsel files a brief pursuant to People v. Wende (1979) 25 Cal.3d 436 [158 Cal.Rptr. 839, 600 P.2d 1071] (Wende), raising no issue for the appellate court’s review, the defendant files supplemental argument', true, 'low_confidence', '{"charge_types":{"independent":0,"same_source":0,"details":[]},"motion_types":{"independent":0,"same_source":0,"details":[]},"defense_theories":{"independent":0,"same_source":0,"details":[]},"motion_outcomes":{"independent":0,"same_source":0,"details":[]}}'::jsonb, 'mechanical_pipeline_phase1', ARRAY['https://www.courtlistener.com/opinion/2588350/people-v-kelly/']::text[]) ON CONFLICT (cluster_id) DO UPDATE SET case_name = EXCLUDED.case_name, court = EXCLUDED.court, jurisdiction = EXCLUDED.jurisdiction, charge_types = EXCLUDED.charge_types, motion_types = EXCLUDED.motion_types, defense_theories = EXCLUDED.defense_theories, motion_outcomes = EXCLUDED.motion_outcomes, motion_favorability = EXCLUDED.motion_favorability, case_favorability = EXCLUDED.case_favorability, holding_text = EXCLUDED.holding_text, classification_confidence = EXCLUDED.classification_confidence, cross_validation_signals = EXCLUDED.cross_validation_signals, classified_at = now(), updated_at = now();
